<script setup lang="ts">
import { computed } from 'vue';
import { route as routeSource, go, setQuery, back } from '../workbench/navigation';
import { flow } from '../workbench/learning-flow';
import { learningSpaces } from '../workbench/learning-space-mock';
import { auditActivities, activityText, executionNames, reviewNames } from '../workbench/activity-review-mock';
import { downloadTrace } from '../workbench/traces';
import PagingBar from './PagingBar.vue';
const route=routeSource,location=window.location;
const students=[...new Map(learningSpaces.map(s=>[s.studentId,{id:s.studentId,name:s.studentName}])).values()];
const spaces=computed(()=>learningSpaces.filter(s=>!route.student||s.studentId===route.student));
const rows=computed(()=>auditActivities().map(r=>{const lesson=flow.lessons.find(a=>a.id===r.activity.id);return {...r,lesson,execution:lesson?(lesson.stage==='finished'?'completed':'running'):r.audit?.execution,chapter:(lesson?.snapshot||r.audit?.snapshot)?.book.units.flatMap(u=>u.chapters).find(c=>c.id===r.activity.chapterId)?.name||'章节未记录'};}));
function dateOnly(value:string){const date=new Date(value);return Number.isNaN(date.getTime())?'':`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
const dateError=computed(()=>route.range==='custom'&&route.since&&route.until&&route.since>route.until?'开始日期不能晚于结束日期。':'');
function inRange(at:string){if(dateError.value)return false;if(!route.range||route.range==='all')return true;const date=dateOnly(at);if(!date)return false;if(route.range==='custom')return (!route.since||date>=route.since)&&(!route.until||date<=route.until);const end=new Date(),start=new Date(end);start.setDate(start.getDate()-(route.range==='7days'?6:route.range==='30days'?29:0));return date>=dateOnly(start.toISOString())&&date<=dateOnly(end.toISOString());}
const filtered=computed(()=>rows.value.filter(r=>(!route.student||r.space.studentId===route.student)&&(!route.filter||r.space.id===route.filter)&&(!route.status||r.execution===route.status)&&(!route.review||r.audit?.review===route.review)&&(!route.result||(route.result==='with'?r.activity.evidence.length>0:r.activity.evidence.length===0))&&inRange(r.activity.at)&&`${r.activity.id} ${r.activity.name} ${r.space.studentId} ${r.space.studentName} ${r.space.name} ${activityText(r.activity)}`.toLowerCase().includes(route.q.trim().toLowerCase())));
const stats=computed(()=>({rounds:filtered.value.reduce((sum,r)=>sum+(r.audit?.rounds.length||0),0),questions:filtered.value.filter(r=>r.audit?.review==='question').length,evidence:filtered.value.reduce((sum,r)=>sum+r.activity.evidence.length,0)}));
const page=computed(()=>Math.min(route.p,Math.max(1,Math.ceil(filtered.value.length/10))));
function open(id:string){go('activity',{id,returnTo:location.hash});}
function reset(){setQuery({q:'',student:'',filter:'',status:'',review:'',result:'',range:'all',since:'',until:'',p:1});}
function exportList(){downloadTrace('activity-review-index.json',{source:'authored-current-course-mock',filters:{student:route.student,space:route.filter,query:route.q,execution:route.status,review:route.review,result:route.result,range:route.range,since:route.since,until:route.until},items:filtered.value.map(r=>({activityId:r.activity.id,name:r.activity.name,spaceId:r.space.id,studentId:r.space.studentId,chapterId:r.activity.chapterId,at:r.activity.at,execution:r.execution||'unrecorded',review:r.audit?.review||'unreviewed',rounds:r.audit?.rounds.length||0,evidenceCount:r.activity.evidence.length}))});}
</script>
<template><div class="wb-page activity-review-list">
  <button v-if="route.returnTo.startsWith('#/dashboard')" class="text-link" @click="back()">← 返回运行总览</button>
  <header class="page-header"><div><h2>交互审查</h2><p class="page-desc">从学习活动进入，逐轮核对输入、实际帮助、处理步骤和评价依据。</p></div><button class="btn" :disabled="!!dateError" @click="exportList">导出筛选结果 JSON</button></header>
  <div class="metric-grid audit-metrics"><div class="metric-card"><span>学习活动</span><strong>{{filtered.length}}</strong><small>当前筛选范围</small></div><div class="metric-card"><span>已记录处理轮次</span><strong>{{stats.rounds}}</strong><small>一项活动可包含多轮</small></div><div class="metric-card"><span>审查有疑点</span><strong>{{stats.questions}}</strong><small>不等于处理失败</small></div><div class="metric-card"><span>Evidence</span><strong>{{stats.evidence}}</strong><small>条数不等于独立作答次数</small></div></div>
  <div class="toolbar"><label class="search-label">搜索活动<input type="search" :value="route.q" placeholder="学生、活动编号、名称或对话内容" @input="setQuery({q:($event.target as HTMLInputElement).value,p:1})"/></label><label>学生<select aria-label="学生" :value="route.student" @change="setQuery({student:($event.target as HTMLSelectElement).value,filter:'',p:1})"><option value="">全部学生</option><option v-for="s in students" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>学习空间<select aria-label="学习空间" :value="route.filter" @change="setQuery({filter:($event.target as HTMLSelectElement).value,p:1})"><option value="">全部空间</option><option v-for="s in spaces" :key="s.id" :value="s.id">{{s.studentName}} · {{s.name}}</option></select></label><label>执行状态<select aria-label="执行状态" :value="route.status" @change="setQuery({status:($event.target as HTMLSelectElement).value,p:1})"><option value="">全部执行状态</option><option v-for="(name,key) in executionNames" :key="key" :value="key">{{name}}</option></select></label><label>审查情况<select aria-label="审查情况" :value="route.review" @change="setQuery({review:($event.target as HTMLSelectElement).value,p:1})"><option value="">全部审查情况</option><option v-for="(name,key) in reviewNames" :key="key" :value="key">{{name}}</option></select></label><label>评价产物<select aria-label="评价产物" :value="route.result" @change="setQuery({result:($event.target as HTMLSelectElement).value,p:1})"><option value="">全部活动</option><option value="with">有 Evidence</option><option value="without">无 Evidence</option></select></label><label>时间段<select aria-label="时间段" :value="route.range||'all'" @change="setQuery({range:($event.target as HTMLSelectElement).value,p:1})"><option value="all">全部时间</option><option value="today">今天</option><option value="7days">最近 7 天</option><option value="30days">最近 30 天</option><option value="custom">自定义日期</option></select></label><template v-if="route.range==='custom'"><label>开始日期<input type="date" :value="route.since" @input="setQuery({since:($event.target as HTMLInputElement).value,p:1})"/></label><label>结束日期<input type="date" :value="route.until" @input="setQuery({until:($event.target as HTMLInputElement).value,p:1})"/></label></template><button class="btn" @click="reset">清除筛选</button></div>
  <p v-if="dateError" class="callout danger" role="alert">{{dateError}}</p><p class="muted">按活动开始日期筛选（本机时区）；统计随筛选更新。示例处理时长不用于真实性能评价。</p>
  <section class="table-card audit-table-wrap"><table class="data-table audit-list-table"><thead><tr><th>活动 / 章节</th><th>学生 / 学习空间</th><th>开始时间</th><th>执行状态</th><th>审查情况</th><th>评价产物</th></tr></thead><tbody><tr v-for="r in filtered.slice((page-1)*10,page*10)" :key="r.activity.id"><td><button class="text-link item-name" @click="open(r.activity.id)">{{r.activity.name}}</button><small>{{r.chapter}} · {{r.lesson?'本轮 mock 交互':(r.audit?.rounds.length||0)+' 轮'}}</small><small>{{r.activity.id}}</small></td><td>{{r.space.studentName}}<small><button class="text-link" @click="go('learning-spaces',{id:r.space.id,tab:'records',returnTo:location.hash})">{{r.space.name}} ↗</button></small></td><td>{{r.activity.at}}</td><td><span class="badge" :class="r.execution==='completed'?'green':'amber'">{{r.lesson?(r.lesson.stage==='finished'?'活动已结束':'活动进行中'):r.execution?executionNames[r.execution]:'未记录'}}</span></td><td><span class="badge" :class="r.audit?.review==='question'?'amber':''">{{r.audit?reviewNames[r.audit.review]:'未复核'}}</span></td><td>{{r.activity.evidence.length}} 条{{r.lesson?' mock 作答依据':' Evidence'}}<small>{{r.lesson?'未运行真实 Evaluation':r.audit?.rounds.some(t=>t.changes.length)?'含分方面判断':'未记录 Belief 更新'}}</small></td></tr></tbody></table><p v-if="!filtered.length" class="empty">没有符合条件的活动。没有记录不代表该学生未掌握。</p></section><PagingBar v-if="filtered.length>10" :total="filtered.length" :page="page"/>
  <details class="legacy-link"><summary>其他记录来源</summary><p class="muted">当前列表包含预写活动和本浏览器新产生的 mock 交互，均可追溯至学习空间。真实会话通过顶部数据来源切换；旧版过程示例保留原关联，不混入当前统计。</p><button class="text-link" @click="go('trace-list',{source:'legacy'})">查看旧版追溯示例 →</button></details>
</div></template>
<style scoped>
.activity-review-list{max-width:1500px}.audit-metrics strong{font-size:26px}.audit-metrics .metric-card{padding:15px 18px}.toolbar{gap:12px}.toolbar label{min-width:145px;flex:1}.toolbar .search-label{min-width:250px;max-width:none;flex:2}.audit-table-wrap{overflow-x:auto}.audit-list-table{min-width:900px}.audit-list-table th:first-child{width:29%}.audit-list-table th:nth-child(2){width:17%}.audit-list-table th:nth-child(3){width:145px}.audit-list-table th:nth-child(4),.audit-list-table th:nth-child(5){width:110px}.item-name{font-size:14px;font-weight:600}.legacy-link{margin-top:24px}.legacy-link p{margin:10px 0}.audit-list-table .badge{white-space:nowrap}
</style>
